def changelog(task_name: str, generated_at: str, executed: list[str], totals: list[str]) -> str:
    lines = [f"# Changelog {task_name}", "", f"Data: {generated_at}", "", "## Executado", ""]
    lines.extend(f"- {item}" for item in executed)
    lines.extend(["", "## Totais", ""])
    lines.extend(f"- {item}" for item in totals)
    return "\n".join(lines)


def top_counter_lines(counter: Counter[str], limit: int = 15, label: str = "count") -> list[str]:
    lines = []
    for key, value in counter.most_common(limit):
        lines.append(f"- `{key}`: {value} {label}")
    return lines


def common_phrases(text_a: str, text_b: str, limit: int = 5) -> list[str]:
    words_a = token_words(text_a)
    words_b = token_words(text_b)
    phrases_a = token_ngrams(words_a, 4) if len(words_a) >= 4 else set(words_a)
    phrases_b = token_ngrams(words_b, 4) if len(words_b) >= 4 else set(words_b)
    shared = phrases_a & phrases_b
    ranked = sorted(shared, key=lambda item: (-len(item.split()), item))
    return ranked[:limit]


def resolve_markdown_target(target: str, source: Path, root: Path) -> str | None:
    clean = target.split("#", 1)[0].strip()
    if not clean or re.match(r"^(https?|mailto|obsidian):", clean, flags=re.IGNORECASE):
        return None
    candidate = (source.parent / clean.replace("/", os.sep)).resolve()
    if candidate.exists():
        return relative_display(candidate, root)
    fallback = (root / clean.replace("/", os.sep)).resolve()
    if fallback.exists():
        return relative_display(fallback, root)
    return None


def build_markdown_index(files: Iterable[FileRecord]) -> dict[str, list[str]]:
    index: dict[str, list[str]] = defaultdict(list)
    for record in files:
        if record.extension != ".md":
            continue
        stem = normalize_text(Path(record.relative_path).stem)
        if stem:
            index[stem].append(record.relative_path)
        index[normalize_text(record.relative_path)] = [record.relative_path]
    return index


def build_file_index(files: Iterable[FileRecord]) -> dict[str, list[str]]:
    index: dict[str, list[str]] = defaultdict(list)
    for record in files:
        variants = {
            normalize_text(record.relative_path),
            normalize_text(record.relative_path.replace("\\", "/")),
            normalize_text(Path(record.relative_path).name),
            normalize_text(Path(record.relative_path).stem),
        }
        for variant in variants:
            if variant:
                index[variant].append(record.relative_path)
    deduped: dict[str, list[str]] = {}
    for key, values in index.items():
        deduped[key] = sorted(dict.fromkeys(values), key=lambda item: item.lower())
    return deduped


def resolve_wikilink_target(
    target: str,
    source: Path,
    root: Path,
    markdown_index: dict[str, list[str]],
    file_index: dict[str, list[str]] | None = None,
) -> list[str]:
    clean = target.split("|", 1)[0].split("#", 1)[0].strip()
    if not clean:
        return []
    candidate_paths: list[str] = []
    path_variant = clean.replace("/", os.sep)
    if Path(path_variant).suffix:
        candidate_paths.append(relative_display((source.parent / path_variant).resolve(), root))
        candidate_paths.append(relative_display((root / path_variant).resolve(), root))
    else:
        candidate_paths.append(relative_display((source.parent / f"{path_variant}.md").resolve(), root))
        candidate_paths.append(relative_display((root / f"{path_variant}.md").resolve(), root))
        normalized_leaf = normalize_text(Path(path_variant).stem)
        candidate_paths.extend(markdown_index.get(normalized_leaf, []))
    if file_index:
        normalized_target = normalize_text(clean)
        normalized_name = normalize_text(Path(path_variant).name)
        normalized_stem = normalize_text(Path(path_variant).stem)
        candidate_paths.extend(file_index.get(normalized_target, []))
        candidate_paths.extend(file_index.get(normalized_name, []))
        candidate_paths.extend(file_index.get(normalized_stem, []))
    unique = []
    seen = set()
    for item in candidate_paths:
        if item not in seen:
            unique.append(item)
            seen.add(item)
    return unique

